"const fs = require('fs');
const path = require('path');

const brainDir = 'C:\\Users\\lorik\\.gemini\\antigravity\\brain\\37c8f14e-7dae-4d39-a052-556aeeead326';
const logFile = path.join(brainDir, '.system_generated', 'logs', 'transcript.jsonl');
const outFile = path.join(brainDir, 'chat_history.md');

try {
  const lines = fs.readFileSync(logFile, 'utf8').split('\n').filter(Boolean);
  let md = '# Antigravity Chat History\n\n';

  lines.forEach((line, i) => {
    try {
      const step = JSON.parse(line);
      if (step.type === 'USER_INPUT') {
        md += `### USER\n\n${step.content}\n\n---\n\n`;
      } else if (step.type === 'PLANNER_RESPONSE' && step.content) {
        md += `### ASSISTANT\n\n${step.content}\n\n---\n\n`;
      }
    } catch (e) {
      // ignore parse errors on trailing lines
    }
  });

  fs.writeFileSync(outFile, md);
  console.log(`Successfully generated markdown log at: ${outFile}`);
} catch (err) {
  console.error('Error converting transcript logs:', err);
}
"

