"const fs = require('fs');
const path = require('path');

const brainDir = 'C:\\Users\\lorik\\.gemini\\antigravity\\brain';
const outputDir = path.join(brainDir, 'all_chats_for_notebooklm');

// Create output directory if it doesn't exist
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

try {
  const folders = fs.readdirSync(brainDir).filter(name => {
    // only capture UUID folders
    return name !== 'tempmediaStorage' && name !== 'all_chats_for_notebooklm' && fs.statSync(path.join(brainDir, name)).isDirectory();
  });

  folders.forEach((folder) => {
    const logFile = path.join(brainDir, folder, '.system_generated', 'logs', 'transcript.jsonl');
    if (!fs.existsSync(logFile)) return;

    try {
      const lines = fs.readFileSync(logFile, 'utf8').split('\n').filter(Boolean);
      let md = `# Antigravity Chat History - Session ${folder}\n\n`;
      let empty = true;

      lines.forEach((line) => {
        try {
          const step = JSON.parse(line);
          if (step.type === 'USER_INPUT') {
            md += `### USER\n\n${step.content}\n\n---\n\n`;
            empty = false;
          } else if (step.type === 'PLANNER_RESPONSE' && step.content) {
            md += `### ASSISTANT\n\n${step.content}\n\n---\n\n`;
            empty = false;
          }
        } catch (e) {}
      });

      if (!empty) {
        const outFile = path.join(outputDir, `chat_${folder}.md`);
        fs.writeFileSync(outFile, md);
        console.log(`Converted: ${folder} -> chat_${folder}.md`);
      }
    } catch (err) {
      console.error(`Failed to convert ${folder}:`, err.message);
    }
  });

  console.log(`\nAll done! All chats compiled into: ${outputDir}`);
} catch (err) {
  console.error('Error scanning brain folder:', err);
}
"
